"""Arithmetic candidates generated by repeated multiplicative shift differences.

Start with F=1/zeta and append b by F(s)/F(s+b).  All coefficients,
merged subset shifts, and simple real-pole terms are retained.  Numerical
evidence never establishes the required uniform signed moment estimate.
"""
from fractions import Fraction as Q
from functools import reduce
from itertools import combinations_with_replacement
from math import isqrt, lcm
from operator import mul
from flint import arb, ctx
from shifted_quotient_candidates import Meter

GRID = ['1/12', '1/6', '1/4', '1/3', '5/12']
SOURCES = ['mu', 'one', 'partial_prime_13']
FLAGS = dict(uniform_signed_bound_proved=False, RH_proved=False,
             finite_prefix_inverse_claimed=False, historical_novelty_claimed=False)


def validate(program):
    if type(program) is not dict or set(program) != {'shifts'}:
        raise ValueError('shifts-only program')
    rows = program['shifts']
    if type(rows) is not list or not 1 <= len(rows) <= 4:
        raise ValueError('one through four positive shifts')
    values = []
    for row in rows:
        if type(row) is not str or not 1 <= len(row) <= 32:
            raise ValueError('bounded rational text')
        try:
            b = Q(row)
        except (ValueError, ZeroDivisionError) as error:
            raise ValueError('rational shift') from error
        if str(b) != row or not 0 < b < 1 or b.denominator > 24:
            raise ValueError('canonical positive shift below one')
        values.append(b)
    if values != sorted(values) or sum(values) >= 1:
        raise ValueError('nondecreasing word with total shift below one')
    if lcm(*(b.denominator for b in values)) > 24:
        raise ValueError('common root degree at most24')
    return tuple(values)


def _fold(word):
    terms = {Q(0): -1}
    for b in word:
        updated = dict(terms)
        for shift, exponent in terms.items():
            updated[shift+b] = updated.get(shift+b, 0)-exponent
        terms = {s: c for s, c in updated.items() if c}
    return sorted(terms.items())


def stencil(program):
    return _fold(validate(program))


def admissible(program):
    word = validate(program)
    compiled = _fold(word)
    if any(c > 1 for _, c in compiled):
        raise ValueError('pilot requires simple positive real poles after merging')
    return word, compiled


def catalogue():
    out = []
    for depth in range(1, 5):
        for raw in combinations_with_replacement(GRID, depth):
            program = {'shifts': list(raw)}
            word = tuple(map(Q, raw))
            row = dict(id=len(out), depth=depth, program=program,
                       stencil=[[str(s), c] for s, c in _fold(word)],
                       normalization=str(reduce(mul, word, Q(1))))
            try:
                admissible(program)
                row.update(eligible=True, rejection=None)
            except ValueError as error:
                row.update(eligible=False, rejection=str(error))
            out.append(row)
    return out


def real(value):
    value = Q(value)
    return arb(value.numerator)/value.denominator


def precision():
    if not 128 <= ctx.prec <= 256:
        raise ValueError('128..256 bit Arb arithmetic')


def horizon(H):
    if type(H) is not int or not 1 <= H <= 262143:
        raise ValueError('complete horizon1..262143')


def normalizer(program, meter):
    word, compiled = admissible(program)
    precision()
    scale = reduce(mul, word, Q(1))
    rows = []
    for shift, exponent in compiled:
        if exponent < 0:
            continue
        residue = 1/real(scale)
        for other, power in compiled:
            if other == shift:
                continue
            meter.charge(256+abs(power)+3)
            residue *= real(1-shift+other).zeta()**power
        coefficient = residue/real(1-shift)
        if not coefficient.is_finite():
            raise ArithmeticError('finite complete normalizer')
        rows.append(dict(shift=str(shift), residue=residue, coefficient=coefficient))
    return rows


def sieve(H, meter):
    horizon(H)
    meter.charge(H+1)
    spf = list(range(H+1))
    for p in range(2, isqrt(H)+1):
        if spf[p] == p:
            meter.charge((H-p*p)//p+1)
            for n in range(p*p, H+1, p):
                if spf[n] == n:
                    spf[n] = p
    return spf


class Workspace:
    def __init__(self, source, H, meter):
        precision(); horizon(H)
        if source not in SOURCES:
            raise ValueError('declared arithmetic source')
        self.source, self.H, self.meter = source, H, meter
        self.spf = sieve(H, meter)
        self.root_cache = {}
        self.live()

    def live(self):
        self.meter.live((len(self.root_cache)+10)*(self.H+1)+4096)

    def roots(self, degree):
        if degree in self.root_cache:
            return self.root_cache[degree]
        if len(self.root_cache) == 4:
            del self.root_cache[next(iter(self.root_cache))]
        result = [arb(0), arb(1)]
        exponent = arb(1)/degree
        for n in range(2, self.H+1):
            self.meter.charge(64)
            result.append(arb(n)**exponent)
        self.root_cache[degree] = result
        self.live()
        return result

    def coefficients(self, program):
        word, _ = admissible(program)
        degree = lcm(*(b.denominator for b in word))
        roots = self.roots(degree)
        exponents = [int(b*degree) for b in word]
        a = [arb(0)]*(self.H+1)
        a[1] = arb(1)
        for p in range(2, self.H+1):
            self.meter.charge()
            if self.spf[p] != p:
                continue
            weights = [1/(roots[p]**e) for e in exponents]
            self.meter.charge(sum(exponents)+len(word))
            power, indices = p, []
            while power <= self.H:
                indices.append(power); power *= p
                self.meter.charge(2)
            K = len(indices)
            current = [arb(1)]*len(word)
            logarithm = [arb(0)]
            for e in range(1, K+1):
                weight = arb(1)
                for j, q in enumerate(weights):
                    current[j] *= q
                    weight *= 1-current[j]
                    self.meter.charge(3)
                if self.source == 'mu' or self.source == 'partial_prime_13' and p <= 13:
                    weight = -weight
                elif self.source == 'partial_prime_13' and e % 2 == 0:
                    weight = -weight
                logarithm.append(weight)
                self.meter.charge()
            local = [arb(1)]
            for e in range(1, K+1):
                coefficient = arb(0)
                for j in range(1, e+1):
                    coefficient += logarithm[j]*local[e-j]
                local.append(coefficient/e)
                self.meter.charge(2*e+1)
            for index, value in zip(indices, local[1:]):
                a[index] = value
        for n in range(2, self.H+1):
            p = self.spf[n]
            rest = n
            while rest % p == 0:
                rest //= p
                self.meter.charge(2)
            if rest > 1:
                a[n] = a[rest]*a[n//rest]
                self.meter.charge(2)
        scale = real(reduce(mul, word, Q(1)))
        a[1] = arb(0)
        self.meter.charge(self.H)
        for n in range(2, self.H+1):
            a[n] /= scale
        self.live()
        return a, degree

    def evaluate(self, program):
        coefficient, degree = self.coefficients(program)
        rows = normalizer(program, self.meter)
        powers = [(row['coefficient'], int((1-Q(row['shift']))*degree)) for row in rows]
        roots = self.roots(degree)
        centered, absolute = [arb(0)]*(self.H+1), [arb(0)]*(self.H+1)
        prefix, envelope = arb(0), arb(0)
        for n in range(1, self.H+1):
            prefix += coefficient[n]
            envelope += abs(coefficient[n])
            main, main_abs = arb(0), arb(0)
            for weight, exponent in powers:
                value = roots[n]**exponent
                main += weight*value
                main_abs += abs(weight)*value
                self.meter.charge(exponent+4)
            centered[n] = prefix-main
            absolute[n] = envelope+main_abs
            self.meter.charge(4)
        self.live()
        return dict(coefficients=coefficient, centered=centered, absolute=absolute, normalizer=rows)

    def baseline(self):
        mu = [0]*(self.H+1); mu[1] = 1
        for n in range(2, self.H+1):
            p = self.spf[n]; rest = n//p
            if rest % p:
                mu[n] = -mu[rest]
            self.meter.charge(4)
        mu[1] = 0
        centered, absolute = [arb(0)]*(self.H+1), [arb(0)]*(self.H+1)
        total, size = 0, 0
        for n in range(1, self.H+1):
            total += mu[n]; size += abs(mu[n])
            centered[n], absolute[n] = arb(total), arb(size)
            self.meter.charge(4)
        self.live()
        return dict(coefficients=list(map(arb, mu)), centered=centered, absolute=absolute, normalizer=[])


def moments(state, scales, meter):
    H = len(state['centered'])-1
    if type(scales) is not list or len(set(scales)) != len(scales):
        raise ValueError('distinct complete block list')
    out = []
    for X in scales:
        if type(X) is not int or X < 1 or 2*X-1 > H:
            raise ValueError('complete integer doubling block')
        energy, absolute = arb(0), arb(0)
        for n in range(X, 2*X):
            energy += state['centered'][n]**2
            absolute += state['absolute'][n]**2
        meter.charge(4*X+2)
        out.append(dict(X=X, energy=energy/(X*X), absolute_energy=absolute/(X*X)))
    return out


def encoded(rows):
    return [dict(X=r['X'], energy=r['energy'].str(45, radius=True),
                 absolute_energy=r['absolute_energy'].str(45, radius=True)) for r in rows]
